const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.93, -29.69]); // Grafton, NSW, Australia
  const startDate = '2020-01-14';
  const endDate = '2020-01-22'; // Inclusive end date for filterDate
  const rainfallThresholdInches = 6.0;
  const rainfallThresholdMm = rainfallThresholdInches * 25.4;

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
                   .filterDate(startDate, endDate)
                   .filterBounds(grafton);

  const imageCount = chirps.size().getInfo();
  if (imageCount === 0) {
    console.log('No CHIRPS images found for the specified date range and location.');
    console.log('A: No');
    return;
  }
  console.log(`Found ${imageCount} CHIRPS images for the period.`);

  // 3. Processing
  // Sum all the daily precipitation images into a single image representing the total.
  const totalPrecipitationImage = chirps.select('precipitation').sum();

  // 4. Calculation
  // Reduce the region to get the total precipitation value at the point.
  // CHIRPS resolution is ~5km, so scale is set accordingly.
  const stats = totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.first().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: grafton,
    scale: 5000,
    maxPixels: 1e9
  });

  const totalRainfallMm = stats.get('precipitation_first').getInfo();
  const pixelCount = stats.get('precipitation_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
      console.log('No valid pixels found at the location.');
      console.log('C2: No Valid Pixels');
      return;
  }

  if (totalRainfallMm === null || typeof totalRainfallMm === 'undefined') {
    console.log('Calculation failed: could not retrieve rainfall value.');
    console.log('C3: Calculation Failure');
    return;
  }

  console.log(`Total rainfall (Jan 14-22, 2020): ${totalRainfallMm.toFixed(2)} mm`);
  console.log(`Threshold for 'Yes': > ${rainfallThresholdMm.toFixed(2)} mm (${rainfallThresholdInches} inches)`);

  if (totalRainfallMm > rainfallThresholdMm) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred during the analysis:', err);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
